<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?><header class="page-head"><p class="eyebrow">Visual identity</p><h1>School branding</h1><p>Brand tokens are shared by supported tenant interfaces.</p></header><?= $this->include('tenant/admin/_messages') ?><div class="split-grid"><section class="panel"><h2>School theme</h2><form method="post" action="<?= site_url('tenant/admin/branding/theme') ?>"><?= csrf_field() ?><?php foreach(['primary_color'=>'Primary','secondary_color'=>'Secondary','accent_color'=>'Accent'] as $name=>$label):?><label><?= $label ?> color<input type="color" name="<?= $name ?>" value="<?= esc($theme[$name]) ?>" required></label><?php endforeach?><button>Save theme</button></form><p class="muted">Logo selection is intentionally handled through the authorized media library rather than an unsafe storage-path field.</p></section><section class="panel"><h2>Department identity</h2><form method="post" action="<?= site_url('tenant/admin/branding/departments') ?>"><?= csrf_field() ?><label>Department<select name="department_id" required><?php foreach($departments as $row):?><option value="<?= $row['id'] ?>"><?= esc($row['name']) ?></option><?php endforeach?></select></label><label>Color<input type="color" name="color_hex" value="#0f766e" required></label><label>Icon key<input name="icon_key" placeholder="health-sciences"></label><button>Save department identity</button></form><p class="muted"><?= count($identities) ?> configured department identity record(s).</p></section></div><?= $this->endSection() ?>
